const home = join(units, 'home'), tmp = join(units, 'tmp'), hooks = join(units, 'empty-hooks');
for (const path of [home, tmp, hooks]) mkdirSync(path, { mode: 0o700 });
// Child-local environment isolation; inherited preload and all other variables stay intact.
Object.assign(process.env, { HOME: home, USERPROFILE: home, XDG_CONFIG_HOME: home,
  TMPDIR: tmp, TMP: tmp, TEMP: tmp, GIT_CONFIG_NOSYSTEM: '1', GIT_CONFIG_GLOBAL: join(home, 'empty-gitconfig') });
writeFileSync(process.env.GIT_CONFIG_GLOBAL, '', { flag: 'wx', mode: 0o600 });
